flag, gcc.detail_budgeting_allowed_flag from staging.gl_code_combinations gcc left join ( staging.fnd_flex_values_vl ffvl_s1 inner join staging.fnd_flex_value_sets ffvs_s1 on ffvs_s1.flex_value_set_id = ffvl_s1.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s1 on fifs_s1.flex_value_set_id = ffvl_s1.flex_value_set_id and fifs_s1.segment_num = 1 and fifs_s1.id_flex_code = 'gl#' ) on fifs_s1.id_flex_num = gcc.chart_of_accounts_id and gcc.segment1 = ffvl_s1.flex_value left join ( staging.fnd_flex_values_vl ffvl_s2 inner join staging.fnd_flex_value_sets ffvs_s2 on ffvs_s2.flex_value_set_id = ffvl_s2.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s2 on fifs_s2.flex_value_set_id = ffvl_s2.flex_value_set_id and fifs_s2.segment_num = 2 and fifs_s2.id_flex_code = 'gl#' ) on fifs_s2.id_flex_num = gcc.chart_of_accounts_id and gcc.segment2 = ffvl_s2.flex_value left join ( staging.fnd_flex_values_vl ffvl_s3 inner join staging.fnd_flex_value_sets ffvs_s3 on ffvs_s3.flex_value_set_id = ffvl_s3.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s3 on fifs_s3.flex_value_set_id = ffvl_s3.flex_value_set_id and fifs_s3.segment_num = 3 and fifs_s3.id_flex_code = 'gl#' ) on fifs_s3.id_flex_num = gcc.chart_of_accounts_id and gcc.segment3 = ffvl_s3.flex_value left join ( staging.fnd_flex_values_vl ffvl_s4 inner join staging.fnd_flex_value_sets ffvs_s4 on ffvs_s4.flex_value_set_id = ffvl_s4.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s4 on fifs_s4.flex_value_set_id = ffvl_s4.flex_value_set_id and fifs_s4.segment_num = 4 and fifs_s4.id_flex_code = 'gl#' ) on fifs_s4.id_flex_num = gcc.chart_of_accounts_id and gcc.segment4 = ffvl_s4.flex_value left join ( staging.fnd_flex_values_vl ffvl_s5 inner join staging.fnd_flex_value_sets ffvs_s5 on ffvs_s5.flex_value_set_id = ffvl_s5.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s5 on fifs_s5.flex_value_set_id = ffvl_s5.flex_value_set_id and fifs_s5.segment_num = 5 and fifs_s5.id_flex_code = 'gl#' ) on fifs_s5.id_flex_num = gcc.chart_of_accounts_id and gcc.segment5 = ffvl_s5.flex_value left join ( staging.fnd_flex_values_vl ffvl_s6 inner join staging.fnd_flex_value_sets ffvs_s6 on ffvs_s6.flex_value_set_id = ffvl_s6.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s6 on fifs_s6.flex_value_set_id = ffvl_s6.flex_value_set_id and fifs_s6.segment_num = 6 and fifs_s6.id_flex_code = 'gl#' ) on fifs_s6.id_flex_num = gcc.chart_of_accounts_id and gcc.segment6 = ffvl_s6.flex_value left join ( staging.fnd_flex_values_vl ffvl_s7 inner join staging.fnd_flex_value_sets ffvs_s7 on ffvs_s7.flex_value_set_id = ffvl_s7.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s7 on fifs_s7.flex_value_set_id = ffvl_s7.flex_value_set_id and fifs_s7.segment_num = 7 and fifs_s7.id_flex_code = 'gl#' ) on fifs_s7.id_flex_num = gcc.chart_of_accounts_id and gcc.segment7 = ffvl_s7.flex_value left join ( staging.fnd_flex_values_vl ffvl_s8 inner join staging.fnd_flex_value_sets ffvs_s8 on ffvs_s8.flex_value_set_id = ffvl_s8.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s8 on fifs_s8.flex_value_set_id = ffvl_s8.flex_value_set_id and fifs_s8.segment_num = 8 and fifs_s8.id_flex_code = 'gl#' ) on fifs_s8.id_flex_num = gcc.chart_of_accounts_id and gcc.segment8 = ffvl_s8.flex_value left join ( staging.fnd_flex_values_vl ffvl_s9 inner join staging.fnd_flex_value_sets ffvs_s9 on ffvs_s9.flex_value_set_id = ffvl_s9.flex_value_set_id inner join staging.fnd_id_flex_segments fifs_s9 on fifs_s9.flex_value_set_id = ffvl_s9.flex_value_set_id and fifs_s9.segment_num = 9 and fifs_s9.id_flex_code = 'gl#' ) on fifs_s9.id_flex_num = gcc.chart_of_accounts_id and gcc.segment9 = ffvl_s9.flex_value
